import{SIDE_DIALOGUE}from'./scenario.js';import{applyDialogueEffect,record}from'./model.js';
export function createVNController({vn,titleEl,speakerEl,textEl,choicesEl,runtime,onClose}){let active=false,nodeId=null;function start(){active=true;nodeId='start';runtime.setInputContext('vn');runtime.setPaused(true);runtime.state.activity.focusedExchangeSeen=true;vn.hidden=false;record(runtime.state,'vn_open',{scene:'side_exchange'});render();}function render(){const n=SIDE_DIALOGUE[nodeId];if(!n)return close();titleEl.textContent='By the old doorway';speakerEl.textContent=n.speaker;textEl.textContent=typeof n.text==='function'?n.text(runtime.state):n.text;choicesEl.replaceChildren();if(n.end){const b=document.createElement('button');b.className='continue';b.textContent='Back to the wall';b.onclick=()=>{applyDialogueEffect(runtime.state,n.effect);close();};choicesEl.append(b);return;}for(const[i,c]of n.choices.entries()){const b=document.createElement('button');b.dataset.choice=c.id;b.textContent=`${i+1}. ${c.text}`;b.onclick=()=>select(c);choicesEl.append(b);}}function select(c){record(runtime.state,'vn_choice',{choiceId:c.id,from:nodeId});applyDialogueEffect(runtime.state,c.effect);nodeId=c.next;render();}function close(){if(!active)return;active=false;vn.hidden=true;runtime.setPaused(false);runtime.setInputContext('world');runtime.afterStateChange();onClose?.();}function handleKey(k){if(!active)return false;if(k==='escape'){close();return true;}if(/^[1-4]$/.test(k)){const b=choicesEl.querySelectorAll('button[data-choice]')[Number(k)-1];if(b){b.click();return true;}}if((k==='enter'||k===' ')&&choicesEl.children.length===1&&choicesEl.firstElementChild.classList.contains('continue')){choicesEl.firstElementChild.click();return true;}return false;}return{start,handleKey,get active(){return active;}};}
